package net.civeira.phylax.feature.observe.config;

import jakarta.enterprise.context.ApplicationScoped;
import jakarta.enterprise.event.Observes;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.feature.observe.observabilityconfig.domain.event.ObservabilityConfigCreateEvent;
import net.civeira.phylax.feature.observe.observabilityconfig.domain.event.ObservabilityConfigDeleteEvent;
import net.civeira.phylax.feature.observe.observabilityconfig.domain.event.ObservabilityConfigUpdateEvent;
import net.civeira.phylax.feature.observe.observedsource.domain.event.ObservedSourceCreateEvent;
import net.civeira.phylax.feature.observe.observedsource.domain.event.ObservedSourceDeleteEvent;
import net.civeira.phylax.feature.observe.observedsource.domain.event.ObservedSourceDisableEvent;
import net.civeira.phylax.feature.observe.observedsource.domain.event.ObservedSourceEnableEvent;
import net.civeira.phylax.feature.observe.observedsource.domain.event.ObservedSourceUpdateEvent;
import net.civeira.phylax.feature.observe.source.SourceRegistry;

/**
 * The changes made from the admin (CRUD of observability-config and observed-source) reach the
 * collector in about a second, instead of waiting for the periodic reload.
 */
@ApplicationScoped
@RequiredArgsConstructor
public class ObserveChangeListener {

  private final ObservabilitySettings settings;
  private final SourceRegistry registry;

  void onConfigCreate(@Observes final ObservabilityConfigCreateEvent event) {
    settings.invalidate();
  }

  void onConfigUpdate(@Observes final ObservabilityConfigUpdateEvent event) {
    settings.invalidate();
  }

  void onConfigDelete(@Observes final ObservabilityConfigDeleteEvent event) {
    settings.invalidate();
  }

  void onSourceCreate(@Observes final ObservedSourceCreateEvent event) {
    registry.invalidate();
  }

  void onSourceUpdate(@Observes final ObservedSourceUpdateEvent event) {
    registry.invalidate();
  }

  void onSourceEnable(@Observes final ObservedSourceEnableEvent event) {
    registry.invalidate();
  }

  void onSourceDisable(@Observes final ObservedSourceDisableEvent event) {
    registry.invalidate();
  }

  void onSourceDelete(@Observes final ObservedSourceDeleteEvent event) {
    registry.invalidate();
  }
}
